"""A ledger of harvests."""


class HarvestLedger:
    def __init__(self, harvests=()):
        self._harvests = list(harvests)

    def harvests(self):
        """Return the harvests held (a copy, so callers cannot change the ledger)."""
        return list(self._harvests)

    def add(self, harvest):
        """Add one harvest to the ledger."""
        self.harvests().append(harvest)

    def total(self):
        """Return the total kilos of the harvests held."""
        return sum(x.kilos for x in self._harvests)


def largest_kilos(harvests):
    """Return the largest kilos, or None when there are no harvests."""
    values = [x.kilos for x in harvests]
    return max(values) if values else None


def field_names(harvests):
    """Return the distinct field values, in first-seen order."""
    names = []
    for x in harvests:
        if x.field not in names:
            names.append(x.field)
    return names
